<script setup lang="ts">import type{UvBreadcrumbItem}from './breadcrumb.types';interface Props{items:UvBreadcrumbItem[];label?:string;separator?:string};withDefaults(defineProps<Props>(),{label:'Breadcrumb',separator:'/'})</script>
<template><nav class="uv-breadcrumb" :aria-label="label"><ol><li v-for="(item,index) in items" :key="`${item.label}-${index}`"><span v-if="index" class="uv-breadcrumb__separator" aria-hidden="true">{{separator}}</span><a v-if="item.href&&index<items.length-1" :href="item.href">{{item.label}}</a><span v-else :aria-current="index===items.length-1?'page':undefined">{{item.label}}</span></li></ol></nav></template>
<style>.uv-breadcrumb ol{display:flex;align-items:center;gap:.5rem;list-style:none;margin:0;padding:0;font-family:var(--uv-font-sans,system-ui,sans-serif);font-size:.875rem}.uv-breadcrumb li{display:flex;align-items:center;gap:.5rem}.uv-breadcrumb a{color:var(--uv-color-primary,#2563eb);text-decoration:none}.uv-breadcrumb a:hover{text-decoration:underline}.uv-breadcrumb__separator{color:var(--uv-color-text-muted,#64748b)}.uv-breadcrumb [aria-current=page]{color:var(--uv-color-text,#0f172a);font-weight:700}</style>
